(() => {
  const root=document.querySelector('[data-my-franklin]'); if(!root)return;
  const prefKey='franklinNavigator.myFranklin.v1';
  const reminderKey='franklinNavigator.reminders.v1';
  const form=root.querySelector('form:not([data-franklin-reminder-form])'), output=root.querySelector('[data-my-franklin-output]'), status=root.querySelector('[data-my-franklin-status]'), clear=root.querySelector('[data-my-franklin-clear]');
  const reminderForm=root.querySelector('[data-franklin-reminder-form]'), reminderList=root.querySelector('[data-franklin-reminders]');
  const routes={
    newcomer:['New to Franklin','/new-to-franklin/'], homeowner:['Home & property','/home-property-help/'], renter:['Housing & renter starting help','/housing/'], children:['Schools & family','/school-enrollment/'], caregiver:['Senior & caregiving','/local-pathways/seniors-caregiving/'], transit:['Transportation & mobility','/getting-around/'], business:['For Business','/business-dashboard/'], civic:['Civic & neighborhood','/local-pathways/civic-neighborhood/'], events:['Today & local events','/today/'], jobs:['Jobs & career','/local-pathways/jobs-career/'], parks:['Parks & community','/community/']
  };
  const safeParse=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}};
  const readPrefs=()=>safeParse(prefKey,null);
  const readReminders=()=>{const value=safeParse(reminderKey,[]);return Array.isArray(value)?value:[]};
  const saveReminders=value=>localStorage.setItem(reminderKey,JSON.stringify(value.slice(0,25)));
  const render=data=>{output.replaceChildren();const selected=data?.interests||[];const heading=document.createElement('h2');heading.textContent='Your Franklin starting points';output.append(heading);if(!selected.length){const p=document.createElement('p');p.textContent='Choose what matters to you and save it on this device to build a shorter personal dashboard.';output.append(p);return}const grid=document.createElement('div');grid.className='grid three';for(const id of selected){if(!routes[id])continue;const [label,href]=routes[id];const card=document.createElement('article');card.className='card';const h=document.createElement('h3');h.textContent=label;const p=document.createElement('p');p.textContent='Keep this Franklin topic close at hand.';const a=document.createElement('a');a.href=href;a.textContent='Open';card.append(h,p,a);grid.append(card)}output.append(grid);const today=document.createElement('p');today.innerHTML='<a class="button primary" href="/today/">See what matters today</a> <a class="button" href="/#ask-navigator">Ask Navigator</a>';output.append(today)};
  const renderReminders=()=>{if(!reminderList)return;reminderList.replaceChildren();const items=readReminders().sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.createdAt.localeCompare(b.createdAt));if(!items.length){const p=document.createElement('p');p.className='empty-state';p.textContent='No local reminders saved yet.';reminderList.append(p);return}const list=document.createElement('ul');list.className='reminder-list';for(const item of items){const li=document.createElement('li');const text=document.createElement('span');text.textContent=item.date?`${item.label} — ${item.date}`:item.label;const remove=document.createElement('button');remove.type='button';remove.className='button small';remove.textContent='Remove';remove.addEventListener('click',()=>{saveReminders(readReminders().filter(row=>row.id!==item.id));renderReminders()});li.append(text,remove);list.append(li)}reminderList.append(list)};
  const load=data=>{if(!data)return;form.querySelectorAll('input[name="interests"]').forEach(input=>input.checked=(data.interests||[]).includes(input.value));const area=form.elements.area;if(area)area.value=data.area||'franklin';render(data);status.textContent='Saved preferences loaded from this device.'};
  form.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(form),data={area:String(fd.get('area')||'franklin'),interests:fd.getAll('interests').map(String),savedAt:new Date().toISOString()};localStorage.setItem(prefKey,JSON.stringify(data));render(data);status.textContent='Saved on this device only. Nothing was sent to Franklin Navigator.'});
  clear.addEventListener('click',()=>{localStorage.removeItem(prefKey);localStorage.removeItem(reminderKey);form.reset();render(null);renderReminders();status.textContent='Saved Franklin preferences and reminders were removed from this device.'});
  if(reminderForm)reminderForm.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(reminderForm),label=String(fd.get('label')||'').trim().replace(/\s+/g,' ').slice(0,120),date=String(fd.get('date')||'');if(!label)return;const items=readReminders();items.push({id:`r-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,label,date:/^\d{4}-\d{2}-\d{2}$/.test(date)?date:'',createdAt:new Date().toISOString()});saveReminders(items);reminderForm.reset();renderReminders()});
  const prefs=readPrefs();load(prefs);if(!prefs)render(null);renderReminders();
})();
